using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    static readonly Color Yellow = new Color(1f, 0.816f, 0f, 1f);
    static readonly Color YellowBright = new Color(1f, 0.894f, 0.36f, 1f);
    static readonly Color DarkBg = new Color(0.043f, 0.075f, 0.110f, 0.95f);
    static readonly Color DarkSteel = new Color(0.095f, 0.133f, 0.176f, 0.92f);
    static readonly Color TextPrimary = new Color(0.94f, 0.95f, 0.96f, 1f);
    static readonly Color TextSecondary = new Color(0.576f, 0.635f, 0.686f, 1f);

    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        if (EditorApplication.isPlaying)
        {
            ctx.ReturnValue = "playing - abort";
            return;
        }

        var scene = EditorSceneManager.OpenScene("Assets/Project/LoginMenu.unity");
        sb.AppendLine("opened " + scene.path);

        var chamferPanel = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/HUD_Chamfer_Panel_Yellow.png");
        var chamferBorder = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/HUD_Chamfer_Yellow_Border.png");
        var chamferFill = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/HUD_Chamfer_Yellow_Fill.png");
        var chamferDark = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/HUD_Chamfer_Dark_Border.png");
        var logo = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/Logo_Railbound_Yellow.png");
        sb.AppendLine("sprites panel=" + (chamferPanel != null) + " fill=" + (chamferFill != null) + " logo=" + (logo != null));

        // Branding defaults on LoginUI
        var loginUi = Object.FindObjectOfType<LoginUI>(true);
        if (loginUi == null)
        {
            ctx.ReturnValue = "LoginUI missing";
            return;
        }
        ctx.RegisterObjectModification(loginUi);
        var so = new SerializedObject(loginUi);
        so.FindProperty("defaultGameTitle").stringValue = "RAILBOUND";
        so.FindProperty("defaultSubtitle").stringValue = "ENTER THE IRONLINE";
        so.ApplyModifiedPropertiesWithoutUndo();

        if (loginUi.gameTitle != null)
        {
            ctx.RegisterObjectModification(loginUi.gameTitle);
            loginUi.gameTitle.text = "RAILBOUND";
            loginUi.gameTitle.color = Yellow;
            loginUi.gameTitle.fontStyle = FontStyles.Bold;
        }
        if (loginUi.subtitle != null)
        {
            ctx.RegisterObjectModification(loginUi.subtitle);
            loginUi.subtitle.text = "ENTER THE IRONLINE";
            loginUi.subtitle.color = TextSecondary;
        }

        // Restyle key panels / buttons
        int imageCount = 0, textCount = 0, buttonCount = 0;
        foreach (var img in Object.FindObjectsOfType<Image>(true))
        {
            if (EditorUtility.IsPersistent(img.gameObject)) continue;
            var n = img.gameObject.name;
            ctx.RegisterObjectModification(img);

            if (n.Contains("Background") || n == "Bg" || n.Contains("Dim"))
            {
                img.color = new Color(0.02f, 0.04f, 0.06f, 1f);
                imageCount++;
            }
            else if (n.Contains("LoginDock") || n.Contains("LoginPanel") || n.Contains("Card") || n.Contains("Popup") && img.GetComponent<Button>() == null)
            {
                if (chamferDark != null) { img.sprite = chamferDark; img.type = Image.Type.Sliced; }
                img.color = DarkSteel;
                imageCount++;
            }
            else if (n.Contains("DockAccent") || n.Contains("CardAccent") || n.Contains("Accent") || n.Contains("Divider"))
            {
                img.color = Yellow;
                imageCount++;
            }
            else if (n.Contains("BtnBorder") || n.Contains("Border"))
            {
                if (chamferBorder != null) { img.sprite = chamferBorder; img.type = Image.Type.Sliced; }
                img.color = Yellow;
                imageCount++;
            }
        }

        // Primary Guest CTA
        if (loginUi.registerButton != null)
        {
            var img = loginUi.registerButton.GetComponent<Image>();
            if (img != null)
            {
                ctx.RegisterObjectModification(img);
                if (chamferFill != null) { img.sprite = chamferFill; img.type = Image.Type.Sliced; }
                img.color = Yellow;
            }
            var label = loginUi.registerButton.GetComponentInChildren<TMP_Text>(true);
            if (label != null)
            {
                ctx.RegisterObjectModification(label);
                label.text = "PLAY AS GUEST";
                label.color = new Color(0.05f, 0.06f, 0.08f, 1f);
                label.fontStyle = FontStyles.Bold;
            }
            EnsureHover(loginUi.registerButton.gameObject);
            buttonCount++;
        }

        // Google / More outlined style
        void StyleOutlineButton(Button b, string labelText)
        {
            if (b == null) return;
            var img = b.GetComponent<Image>();
            if (img != null)
            {
                ctx.RegisterObjectModification(img);
                if (chamferBorder != null) { img.sprite = chamferBorder; img.type = Image.Type.Sliced; }
                img.color = new Color(Yellow.r, Yellow.g, Yellow.b, 0.85f);
            }
            var label = b.GetComponentInChildren<TMP_Text>(true);
            if (label != null && !string.IsNullOrEmpty(labelText))
            {
                ctx.RegisterObjectModification(label);
                label.text = labelText;
                label.color = TextPrimary;
            }
            EnsureHover(b.gameObject);
            buttonCount++;
        }
        StyleOutlineButton(loginUi.googleLoginButton, "CONTINUE WITH GOOGLE");
        StyleOutlineButton(loginUi.moreButton, "ACCOUNT LOGIN");
        StyleOutlineButton(loginUi.loginButton, "DEPLOY LOGIN");
        StyleOutlineButton(loginUi.createButton, "CREATE OPERATOR");

        // Checkbox colors already coded; update BuildTag / status
        foreach (var tmp in Object.FindObjectsOfType<TMP_Text>(true))
        {
            if (EditorUtility.IsPersistent(tmp.gameObject)) continue;
            var n = tmp.gameObject.name;
            if (n == "BuildTag")
            {
                ctx.RegisterObjectModification(tmp);
                tmp.text = "RAILBOUND  |  SEASON 01  |  WARZONE LOBBY BUILD";
                tmp.color = TextSecondary;
                textCount++;
            }
            else if (n.Contains("PopupTitle") || n.Contains("Title") && tmp.text.ToUpper().Contains("LOGIN"))
            {
                ctx.RegisterObjectModification(tmp);
                tmp.color = Yellow;
                textCount++;
            }
        }

        // Add logo image near title if possible
        if (logo != null && loginUi.gameTitle != null)
        {
            var parent = loginUi.gameTitle.transform.parent;
            var existing = parent.Find("Logo_Railbound_Yellow");
            if (existing == null)
            {
                var go = new GameObject("Logo_Railbound_Yellow", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
                ctx.RegisterObjectCreation(go);
                go.transform.SetParent(parent, false);
                go.transform.SetAsFirstSibling();
                var rt = go.GetComponent<RectTransform>();
                rt.anchorMin = new Vector2(0.5f, 1f);
                rt.anchorMax = new Vector2(0.5f, 1f);
                rt.pivot = new Vector2(0.5f, 1f);
                rt.sizeDelta = new Vector2(220f, 64f);
                rt.anchoredPosition = new Vector2(0f, 40f);
                var img = go.GetComponent<Image>();
                img.sprite = logo;
                img.preserveAspect = true;
                img.color = Color.white;
                sb.AppendLine("added logo");
            }
        }

        // Reach-style: ensure CanvasScaler reference resolution looks desktop
        var canvas = GameObject.Find("Canvas");
        if (canvas != null)
        {
            var scaler = canvas.GetComponent<CanvasScaler>();
            if (scaler != null)
            {
                ctx.RegisterObjectModification(scaler);
                scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
                scaler.referenceResolution = new Vector2(1920, 1080);
                scaler.matchWidthOrHeight = 0.5f;
            }
        }

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("saved images=" + imageCount + " buttons=" + buttonCount + " texts=" + textCount);
        ctx.ReturnValue = sb.ToString();
    }

    static void EnsureHover(GameObject go)
    {
        if (go.GetComponent<Railbound.UI.TacticalUIHoverEffect>() == null)
            go.AddComponent<Railbound.UI.TacticalUIHoverEffect>();
    }
}
